-- A131-01 · verfahren_n_elim — Verfahren zur Stickstoffelimination
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Stickstoffelimination sind unterschiedliche Bau- und Betriebsweisen der Belebungsbecken möglich (Bild 2); diese lassen sich wie folgt charakterisieren (siehe ATV 1997a: 5.2.5 und 5.3.2), wobei die oben angeführten Forderungen stets zu beachten sind: | Vorgeschaltete Denitrifikation: Abwasser, Rücklaufschlamm und interne Rezirkulation werden im Denitrifikationsbecken vermischt. | Kaskadendenitrifikation: Zwei oder mehr Belebungsbecken, jedes mit vorgeschalteter oder simultaner Denitrifikation, werden nacheinander durchflossen. | Simultane Denitrifikation: Praktisch nur in Umlaufbecken realisierbar. — printed p.18–21', verification_note='md-verified 2026-09-07 (§3.2, printed p.18–21) [VC]', verified_at=now() where id='91c7db7d-35a1-4c61-b771-1c6e8036e712' and verification_status not in ('verified_against_standard','corrected');

