update public.fields set verification_status='verified_against_standard', verification_quote='Die Schwankung der Stickstofffracht im Zulauf zur Belebung wird durch den Stoßfaktor $f_{\mathrm{N}}$ als die höchste tägliche 2 -h-KN-Fracht ( $B_{2 h, K N, Z B, \text { max }}$ ) bezogen auf die mittlere KN-Tagesfracht ( $B_{2 h, K N, Z B, d M}$ ) ausgedrückt. | Der Stoßfaktor $f_{\mathrm{N}}$ ist wegen des großen Einflusses der Stickstoffschwankungen auf den erforderlichen Volumenbedarf für die Nitrifikation und die Auslegung der Belüftung bei bestehenden Anlagen immer messtechnisch zu ermitteln. — printed p.30–31', verification_note='md-verified 2026-09-07 (§5.1.3, printed p.30–31) [VC]', verified_at=now() where id='67314605-ea69-44af-b05e-34f96b60e503' and verification_status not in ('verified_against_standard','corrected');

