update public.fields set verification_status='verified_against_standard', verification_quote='Im Zulauf sind die Nitratstickstoffkonzentrationen ( $\mathrm{S}_{\mathrm{N} 03, \mathrm{ZB}}$ ) im Allgemeinen vernachlässigbar gering. Bei höheren Fremdwasserzuflüssen (nitrathaltiges Grundwasser) oder bei Zuflüssen aus bestimmten Gewerbe- und Industriebetrieben kann es erforderlich sein, $S_{\mathrm{N} 03, \mathrm{ZB}}$ in $C_{\mathrm{N}, \mathrm{ZB}}$ zu berücksichtigen. — printed p.34–35', verification_note='md-verified 2026-09-07 (§5.2.3, printed p.34–35) [VC]', verified_at=now() where id='de17ad8b-abf2-41f4-9fd6-0ff7094e36c6' and verification_status not in ('verified_against_standard','corrected');

