update public.fields set verification_status='verified_against_standard', verification_quote='In einem ersten Schritt wird der gesamte Sauerstoffverbrauch für den Kohlenstoffabbau $O V_{\mathrm{C}}$ aus der CSB-Bilanz errechnet: | O V_{C}=C_{C S B, \mathrm{abb}, \mathrm{ZB}}+C_{C S B, \mathrm{dos}}-X_{C S B, \mathrm{BM}}-X_{C S B, \text { inert,BM }}(\mathrm{mg} / \mathrm{l}) \tag{27} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, printed p.35–36) [VC]', verified_at=now() where id='75d6acc1-902f-41af-9848-14b251ecabe9' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · OV_C_la_vorg — O2-Bedarf leicht abb. CSB vorgeschaltet
update public.fields set verification_status='verified_against_standard', verification_quote='Für die vorgeschaltete Denitrifikation ergibt sich für diesen Anteil: | O V_{\mathrm{C}, \mathrm{la}, \mathrm{vorg}}=f_{\mathrm{CSB}} \cdot C_{\mathrm{CSB}, \mathrm{abb}, \mathrm{ZB}} \cdot(1-Y)+C_{\mathrm{CSB}, \mathrm{dos}} \cdot\left(1-Y_{\mathrm{CSB}, \mathrm{dos}}\right)(\mathrm{mg} / \mathrm{l}) \tag{28} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, printed p.35–36) [VC]', verified_at=now() where id='875bcf38-b7eb-45ee-ba87-086ede6509f7' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · OV_C_la_int — O2-Bedarf extern dosierter C intermittierend
update public.fields set verification_status='verified_against_standard', verification_quote='Für die intermittierende Denitrifikation kann nur die extern dosierte Kohlenstoffquelle separat gerechnet werden. Wenn diese während der Denitrifikationszeit dosiert wird, dann ergibt sich: | O V_{\text {C,la,int }}=C_{\text {CSB,dos }} \cdot\left(1-Y_{\text {CSB,dos }}\right)(\mathrm{mg} / \mathrm{l}) \tag{29} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, printed p.35–36) [VC]', verified_at=now() where id='38c21789-f9d4-45cf-a72e-05611a030196' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · OV_C_D — O2-Verbrauch in der Denitrifikationszone (maßgebend)
update public.fields set verification_status='verified_against_standard', verification_quote='Der gesamte Sauerstoffverbrauch in der Denitrifikationszone ergibt sich dann für die verschiedenen Verfahren wie folgt: | Dabei wird der Sauerstoffverbrauch für die Denitrifikation um den Faktor 0,75 für die verminderte Umsetzung mit Nitrat als Elektronenakzeptor reduziert und mit dem Volumenanteil der Denitrifikation multipliziert. — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, printed p.35–36) [VC]', verified_at=now() where id='c68b1ed3-a2c4-4648-8f7f-4f39f0dc158d' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · OV_C_D_vorg — O2-Verbrauch Deni-Zone, vorgeschaltet
update public.fields set verification_status='verified_against_standard', verification_quote='vorgeschaltete Denitrifikation: | O V_{C, D}=0,75 \cdot\left[O V_{C, l, \text { vorg }}+\left(O V_{C}-O V_{C, l, \text { avorg }}\right) \cdot\left(V_{D} / V_{B B}\right)^{0,68}\right](\mathrm{mg} / \mathrm{l}) \tag{30} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, printed p.35–36) [VC]', verified_at=now() where id='2fafae08-94a3-4065-b3d3-278468788ec9' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · OV_C_D_int — O2-Verbrauch Deni-Zone, intermittierend
update public.fields set verification_status='verified_against_standard', verification_quote='intermittierende Denitrifikation mit Dosierung von externem Substrat während der Denitrifikationszeit: | O V_{C, D}=0,75 \cdot\left[O V_{C, l \mathrm{a}, \text { int }}+\left(O V_{C}-O V_{C, l \mathrm{a}, \text { int }}\right) \cdot\left(V_{D} / V_{B B}\right)\right](\mathrm{mg} / \mathrm{l}) \tag{31} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, printed p.35–36) [VC]', verified_at=now() where id='b039fce3-4be4-4bea-a68e-51191e5ba23e' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · OV_C_D_sim — O2-Verbrauch Deni-Zone, simultan
update public.fields set verification_status='verified_against_standard', verification_quote='simultane Denitrifikation ohne vorgeschaltete Anaerobbecken: | O V_{C, D}=0,75 \cdot O V_{C} \cdot V_{D} / V_{B B}(\mathrm{mg} / \mathrm{l}) \tag{32} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, printed p.35–36) [VC]', verified_at=now() where id='fd7b28e1-fce5-4e16-b547-453af9575dc8' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · OV_C_D_vg — O2-Verbrauch vorgeschaltete Stufe (Kombination)
update public.fields set verification_status='verified_against_standard', verification_quote='Der Anteil des Sauerstoffverbrauchs der vorgeschalteten Denitrifikationsstufe ergibt sich bei Verfahrenskombination, wenn in GL. (30) der Denitrifikationsanteil des vorgeschalteten Denitrifikationsbeckens eingesetzt wird: | O V_{\mathrm{C}, \mathrm{D}, \mathrm{vg}}=0,75 \cdot\left[O V_{\mathrm{C}, \mathrm{la}, \mathrm{vorg}}+\left(O V_{\mathrm{C}}-O V_{\mathrm{C}, \mathrm{la}, \mathrm{vorg}}\right) \cdot\left(V_{\mathrm{D}, \mathrm{vg}} / V_{\mathrm{BB}}\right)^{0,68}\right](\mathrm{mg} / \mathrm{l}) \tag{33} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, printed p.35–36) [VC]', verified_at=now() where id='8c341593-2829-4fda-a7a4-3aaa71d2adc9' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · V_D_vg_V_BB — Denitrifikationsanteil vorgeschaltetes Becken
update public.fields set verification_status='verified_against_standard', verification_quote='Werden mindestens $0,15 \cdot V_{\mathrm{BB}}$ als vorgeschaltete Denitrifikation ausgeführt, kann das Gesamtsystem ausreichend genau über den Bemessungsansatz für vorgeschaltete Denitrifikation abgebildet werden. — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, printed p.35–36) [VC]', verified_at=now() where id='d3dfdde7-95e9-482c-8da8-cff4d74e77ee' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · x_iter — Iterationskriterium O2-Verbrauch/Dargebot
update public.fields set verification_status='verified_against_standard', verification_quote='Der Nachweis einer ausreichenden Reduzierung der Nitratkonzentration wird über den Vergleich von Sauerstoffzehrung $\left(O V_{C, D}\right)$ zu Sauerstoffangebot aus Nitrat $=2,86 \cdot S_{\mathrm{N} 03, \mathrm{D}}$ geführt. Die Iteration über eine Veränderung der $V_{D} / V_{B B}$ wird so lange geführt, bis der Wert | x=\frac{O V_{C, D}}{2,86 \cdot S_{N O 3, D}} \tag{34} | den Wert 1 annimmt. — printed p.36–37', verification_note='md-verified 2026-09-07 (§5.2.5, printed p.36–37) [VC]', verified_at=now() where id='7c8c2c2f-6b44-4cdb-bdeb-409a9196013d' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · b — Zerfallskoeffizient
update public.fields set verification_status='verified_against_standard', verification_quote='Der Ertragskoeffizient für den abbaubaren CSB im Zulauf wird mit $Y=0,67 \mathrm{~g} / \mathrm{g}$ /g gebildete Biomasse (CSB) pro g abgebautem CSB) und der Zerfallskoeffizient mit $b=0,17 d^{-1}$ bei $15^{\circ} \mathrm{C}$, beide analog wie im Activated Sludge Model No. 1 (Henze et al. 1987), angenommen. — printed p.34', verification_note='md-verified 2026-09-07 (§5.2.2, printed p.34) [VC]', verified_at=now() where id='9cca56dd-336a-4900-8ebe-4ac9a7d475d6' and verification_status not in ('verified_against_standard','corrected');

-- A131-04 · Y — Ertragskoeffizient abbaubarer CSB
