-- A131-05 · faellmittel — Faellmittelart
update public.fields set verification_status='verified_against_standard', verification_quote='Der mittlere Fällmittelbedarf kann mit $1,5 \mathrm{~mol} \mathrm{Me}^{3+} / \mathrm{mol} X_{\text {P, Fäll }}$ berechnet werden. Umgerechnet ergeben sich dann folgende Bedarfswerte: | Fällung mit Eisen: $\quad 2,7 \mathrm{~kg} \mathrm{Fe} / \mathrm{kg} X_{\text {P, Fäll }}$ | Fällung mit Aluminium: $1,3 \mathrm{~kg} \mathrm{Al} / \mathrm{kg} X_{\text {P,Fäll }}$ | Wird zur Fällung Kalk eingesetzt, beträgt die Schlammproduktion $1,35 \mathrm{~kg}$ TS pro kg Calciumhydroxid $\left(\mathrm{Ca}(\mathrm{OH})_{2}\right)$, siehe auch Arbeitsblatt DWA-A 202. — printed p.37–38', verification_note='md-verified 2026-09-07 (§5.3.1, printed p.37–38) [VC]', verified_at=now() where id='cf750c05-972d-440c-b0c2-e7c749701aa0' and verification_status not in ('verified_against_standard','corrected');

