update public.fields set verification_status='verified_against_standard', verification_quote='Die Ablaufkonzentration ( $C_{\text {P,AN }}$ ) ist im Einklang mit dem Überwachungswert ( $C_{\text {P,üw }}$ ) zu wählen, z. B. $C_{\text {P,AN }}=0,6 \cdot C_{\text {P,üw }}$ bis $0,7 \cdot C_{\text {P, Üw }}$. — printed p.37–38', verification_note='md-verified 2026-09-07 (§5.3.1, printed p.37–38) [VC]', verified_at=now() where id='c34995bb-34c3-410c-9ff5-1425204989fb' and verification_status not in ('verified_against_standard','corrected');

-- A131-05 · X_P_BM — In Biomasse eingebauter Phosphor
update public.fields set verification_status='verified_against_standard', verification_quote='Der zum Zellaufbau der heterotrophen Biomasse benötigte Phosphor ( $X_{\text {P, BM }}$ ) kann mit $0,005 C_{\mathrm{CSB}, \mathrm{ZB}}$ angesetzt werden. — printed p.37–38', verification_note='md-verified 2026-09-07 (§5.3.1, printed p.37–38) [VC]', verified_at=now() where id='b43b0296-c223-4578-9749-ec9bee099238' and verification_status not in ('verified_against_standard','corrected');

-- A131-05 · X_P_BioP — Biologisch eliminierter Phosphor
update public.fields set verification_status='verified_against_standard', verification_quote='Bei üblichem kommunalem Abwasser kann für die biologische Phosphorelimination ( $X_{\text {P, Biop }}$ ) angesetzt werden: | $X_{\mathrm{P}, \text { BioP }}=0,005$ bis $0,007 \cdot C_{\mathrm{CSB}, \mathrm{ZB}}$ mit vorgeschaltetem anaerobem Becken. | In Anlagen mit vorgeschalteter Denitrifikation oder Kaskadendenitrifikation, aber ohne anaerobes Becken kann eine biologische Phosphorelimination von $X_{P, B i o P}=0,002 \cdot C_{C S B, Z B}$ angenommen werden. — printed p.37–38', verification_note='md-verified 2026-09-07 (§5.3.1, printed p.37–38) [VC]', verified_at=now() where id='a3268a5b-6b3d-4252-a6ba-d33bed720b0e' and verification_status not in ('verified_against_standard','corrected');

