update public.fields set verification_status='verified_against_standard', verification_quote='Zur Ermittlung des zu fällenden Phosphats ( $X_{\text {P,Fäll }}$ ) ist eine Phosphorbilanz, gegebenenfalls für verschiedene Lastfälle aufzustellen: | X_{P, F \text { äll }}=C_{P, Z B}-C_{P, A N}-X_{P, B M}-X_{P, B i o P}(\mathrm{mg} / \mathrm{l}) \tag{35} — printed p.37–38', verification_note='md-verified 2026-09-07 (§5.3.1, printed p.37–38) [VC]', verified_at=now() where id='f41feeb0-1f30-44b9-83c1-5e46cd90bc13' and verification_status not in ('verified_against_standard','corrected');

-- A131-05 · X_P_Faell_Fe — Mit Eisen gefaellter Phosphor
update public.fields set verification_status='verified_against_standard', verification_quote='Der insgesamt aus der Phosphorelimination resultierende Überschussschlamm (ÜS ${ }_{\mathrm{d}, \mathrm{P}}$ ) ergibt sich damit zu: | \ddot{U} S_{\mathrm{d}, \mathrm{P}}=Q_{\mathrm{d}, \text { Konz }} \cdot\left(3 \cdot X_{\mathrm{P}, \text { BioP }}+6,8 \cdot X_{\mathrm{P}, \text { Fäll, Fe }}+5,3 \cdot X_{\mathrm{P}, \text { Fäll,al }}\right) / 1000(\mathrm{~kg} / \mathrm{d}) \tag{36} — printed p.38', verification_note='md-verified 2026-09-07 (§5.3.2, printed p.38) [VC]', verified_at=now() where id='29304a22-fda2-42d2-8296-ae3300c3c96a' and verification_status not in ('verified_against_standard','corrected');

-- A131-05 · X_P_Faell_Al — Mit Aluminium gefaellter Phosphor
update public.fields set verification_status='verified_against_standard', verification_quote='Der insgesamt aus der Phosphorelimination resultierende Überschussschlamm (ÜS ${ }_{\mathrm{d}, \mathrm{P}}$ ) ergibt sich damit zu: | \ddot{U} S_{\mathrm{d}, \mathrm{P}}=Q_{\mathrm{d}, \text { Konz }} \cdot\left(3 \cdot X_{\mathrm{P}, \text { BioP }}+6,8 \cdot X_{\mathrm{P}, \text { Fäll, Fe }}+5,3 \cdot X_{\mathrm{P}, \text { Fäll,al }}\right) / 1000(\mathrm{~kg} / \mathrm{d}) \tag{36} — printed p.38', verification_note='md-verified 2026-09-07 (§5.3.2, printed p.38) [VC]', verified_at=now() where id='a38d33c1-0fd3-47d8-9434-6a47768b0b99' and verification_status not in ('verified_against_standard','corrected');

-- A131-05 · UeS_d_P — Schlammproduktion aus Phosphorelimination
update public.fields set verification_status='verified_against_standard', verification_quote='Die Schlammproduktion aus der Phosphorelimination setzt sich aus den Feststoffen der biologischen Phosphorelimination und der Simultanfällung zusammen. | Für die biologische Phosphorelimination kann mit 3 g TS pro g biologisch eliminiertem Phosphor gerechnet werden. — printed p.38', verification_note='md-verified 2026-09-07 (§5.3.2, printed p.38) [VC]', verified_at=now() where id='cfe3bcc5-bf81-4433-84db-e91956d25548' and verification_status not in ('verified_against_standard','corrected');

