update public.fields set verification_status='verified_against_standard', verification_quote='Der in einer Belebungsanlage produzierte Schlamm setzt sich aus den beim Abbau organischer Stoffe entstehenden und eingelagerten Feststoffen (siehe 5.2) sowie dem aus der Phosphorelimination resultierenden Schlamm (siehe 5.3) zusammen: | \ddot{U} S_{d}=\ddot{U} S_{d, C}+\ddot{U} S_{d, P}(\mathrm{~kg} / \mathrm{d}) \tag{37} — printed p.38–39', verification_note='md-verified 2026-09-07 (§5.4, printed p.38–39) [VC]', verified_at=now() where id='8997dd20-004a-4a74-a866-24dadfce37ac' and verification_status not in ('verified_against_standard','corrected');

