update public.fields set verification_status='verified_against_standard', verification_quote='$\rho_{0}$ ist die Dichte des belebten Schlamms (z. B. $1.001 \mathrm{~kg} / \mathrm{m}^{3}$ ), die sich aus den Dichten des Fluids und der Trockenmasse ( $\mathrm{z} . \mathrm{B} .1 .450 \mathrm{~kg} / \mathrm{m}^{3}$ ) ergibt — printed p.46–47', verification_note='md-verified 2026-09-07 (§6.8, printed p.46–47) [VC]', verified_at=now() where id='f856e8ce-8d48-4305-9863-fe07f94ed9a2' and verification_status not in ('verified_against_standard','corrected');

