-- A131-06 · h — Oeffnungshoehe Eintrittsquerschnitt
update public.fields set verification_status='verified_against_standard', verification_quote='In der Gleichung ist $u$ die horizontale Strömungsgeschwindigkeit im Eintrittsquerschnitt bei maximalem Zufluss einschließlich Rücklaufschlamm und $h$ die Öffnungshöhe des Eintrittsquerschnitts (Schlitzhöhe). | In der Praxis haben sich Einlaufgestaltungen mit 30 cm bis 60 cm Schlitzhöhe und Eintrittsgeschwindigkeiten $<7 \mathrm{~cm} / \mathrm{s}$ bewährt. — printed p.46–47', verification_note='md-verified 2026-09-07 (§6.8, printed p.46–47) [VC]', verified_at=now() where id='6da670b2-a810-44ad-8a9d-6fa56338b8fa' and verification_status not in ('verified_against_standard','corrected');

-- A131-06 · G — G-Wert (turbulente Scherbeanspruchung)
update public.fields set verification_status='verified_against_standard', verification_quote='Weiterhin sollte für eine gute Flockenbildung in der Einlaufkammer der G-Wert (Maß für die turbulente Scherbeanspruchung) | G=\sqrt{\frac{P_{\mathrm{E}}}{\mu \cdot V_{\mathrm{E}}}}(1 / \mathrm{s}) \tag{47} | bei Mischwasserzulauf zwischen $40 \mathrm{~s}^{-1}$ und $80 \mathrm{~s}^{-1}$ betragen. — printed p.46–47', verification_note='md-verified 2026-09-07 (§6.8, printed p.46–47) [VC]', verified_at=now() where id='5885166c-03a5-4e66-9ce2-7fe6ee1d6aa1' and verification_status not in ('verified_against_standard','corrected');

-- A131-06 · P_E — In Einlaufbauwerk eingetragene Leistung
update public.fields set verification_status='verified_against_standard', verification_quote='Die in das Einlaufbauwerk eingetragene Leistung $P_{\mathrm{E}}$ errechnet sich dabei zu | P_{\mathrm{E}}=0,5 \cdot \rho_{0} \cdot v_{\mathrm{E}}^{2} \cdot Q_{\mathrm{M}} \cdot(1+R V)(\mathrm{Nm} / \mathrm{s}) \tag{48} — printed p.46–47', verification_note='md-verified 2026-09-07 (§6.8, printed p.46–47) [VC]', verified_at=now() where id='88a0f190-5186-4dde-9b94-05fd651bb7de' and verification_status not in ('verified_against_standard','corrected');

