update public.fields set verification_status='verified_against_standard', verification_quote='$V_{\mathrm{E}}$ ist das Volumen des Einlaufbauwerks, $\mu$ die dynamische Viskosität des belebten Schlamms (ca. $0,0013 \mathrm{Ns} / \mathrm{m}^{2}$ bei $10^{\circ} \mathrm{C}$ ). — printed p.46–47', verification_note='md-verified 2026-09-07 (§6.8, printed p.46–47) [VC]', verified_at=now() where id='93fa438f-db18-46b3-951f-ffac4838764b' and verification_status not in ('verified_against_standard','corrected');

