-- A131-06 · v_E — Eintrittsgeschwindigkeit Einlaufbauwerk
update public.fields set verification_status='verified_against_standard', verification_quote='mit der Eintrittsgeschwindigkeit $v_{\mathrm{E}}$ in das Einlaufbauwerk (im Querschnitt Zulaufdüker) | v_{\mathrm{E}}=\frac{Q_{\mathrm{M}} \cdot(1+R V)}{A_{\mathrm{ZD}}}(\mathrm{~m} / \mathrm{s}) \tag{49} — printed p.46–47', verification_note='md-verified 2026-09-07 (§6.8, printed p.46–47) [VC]', verified_at=now() where id='7a88fe29-3244-4c2d-84b0-adbbf0fdd387' and verification_status not in ('verified_against_standard','corrected');

