update public.fields set verification_status='verified_against_standard', verification_quote='$A_{\mathrm{ZD}}$ ist die Querschnittsfläche des Zulaufdükers in das Einlaufbauwerk. Ausführliche Hinweise zur Einlaufgestaltung finden sich in DWA (2013). — printed p.46–47', verification_note='md-verified 2026-09-07 (§6.8, printed p.46–47) [VC]', verified_at=now() where id='4190305f-b2f8-4de6-b24d-bfd42c9d7044' and verification_status not in ('verified_against_standard','corrected');

-- A131-06 · Q_RS — Ruecklaufschlammstrom
update public.fields set verification_status='verified_against_standard', verification_quote='Der Bemessung von Nachklärung und Belebungsbecken ist ein Rücklaufschlammstrom von maximal 0,75 $\cdot Q_{M}$ zugrunde zu legen. | Bei vertikal durchströmten Nachklärbecken kann die Bemessung für maximal $Q_{\mathrm{RS}}=1,0 \cdot Q_{\mathrm{M}}$ erfolgen; die Auslegung der Rücklaufschlammpumpen (einschließlich Reserve) sollte eine betriebliche Anpassung von $Q_{\mathrm{RS}}$ bis zu 1,5 • $Q_{\mathrm{M}}$ ermöglichen (siehe 8.4). — printed p.41–42', verification_note='md-verified 2026-09-07 (§6.4, printed p.41–42) [VC]', verified_at=now() where id='3a447e73-093d-4712-b9cc-a43d59602bc5' and verification_status not in ('verified_against_standard','corrected');

-- A131-06 · Q_SR — Raeumvolumenstrom (gewaehlt)
update public.fields set verification_status='verified_against_standard', verification_quote='Das Räumsystem muss so ausgelegt werden, dass der geräumte Räumvolumenstrom $Q_{\mathrm{SR}}$ die Feststoffbilanz nach GL. (B.9) erfüllt. — printed p.64', verification_note='md-verified 2026-09-07 (§B.4, printed p.64) [VC]', verified_at=now() where id='70949b28-f76e-4503-9acd-1cbcb78db3a1' and verification_status not in ('verified_against_standard','corrected');

-- A131-06 · Q_SR_rund — Raeumvolumenstrom Schildraeumer Rundbecken
update public.fields set verification_status='verified_against_standard', verification_quote='Der Räumvolumenstrom beträgt für Schildräumer in Rundbecken: | Q_{\mathrm{SR}}=\frac{h_{\mathrm{SR}} \cdot a \cdot v_{\mathrm{SR}} \cdot D_{\mathrm{NB}}}{4 \cdot f_{\mathrm{SR}}}\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{B.4} — printed p.62–63', verification_note='md-verified 2026-09-07 (§B.2, printed p.62–63) [VC]', verified_at=now() where id='0b442109-62db-4f82-bdb9-cbf73eb37eba' and verification_status not in ('verified_against_standard','corrected');

-- A131-06 · Q_SR_recht — Raeumvolumenstrom Schildraeumer Rechteckbecken
update public.fields set verification_status='verified_against_standard', verification_quote='Der Räumvolumenstrom $Q_{\mathrm{SR}}$ ergibt sich bei Annahme eines Abstands des Räumschilds von dem Schlammabzugspunkt beim Einsetzen des Schlammrückflusses von $l_{S R} \approx 15 \cdot h_{S R}$ mit der Räumschildlänge $b_{\mathrm{SR}}\left(\approx b_{\mathrm{NB}}\right.$ in Becken mit senkrechten Wänden) zu: | Q_{\mathrm{SR}}=\frac{h_{\mathrm{SR}} \cdot b_{\mathrm{SR}} \cdot l_{\mathrm{SR}}}{f_{\mathrm{SR}} \cdot t_{\mathrm{SR}}}\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{B.6} — printed p.63–64', verification_note='md-verified 2026-09-07 (§B.3, printed p.63–64) [VC]', verified_at=now() where id='78cca924-a70c-40dd-97eb-af73e6ef79c2' and verification_status not in ('verified_against_standard','corrected');

-- A131-06 · Q_SR_band — Raeumvolumenstrom Bandraeumer
update public.fields set verification_status='verified_against_standard', verification_quote='Der geräumte Schlammvolumenstrom $Q_{\mathrm{SR}}$ beträgt damit für Bandräumer: | Q_{\mathrm{SR}}=\frac{v_{\mathrm{SR}} \cdot b_{\mathrm{SR}} \cdot h_{\mathrm{SR}}}{f_{\mathrm{SR}}}\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{B.8} — printed p.63–64', verification_note='md-verified 2026-09-07 (§B.3, printed p.63–64) [VC]', verified_at=now() where id='6393d038-ca91-4f93-bda2-0a6ad4decb3d' and verification_status not in ('verified_against_standard','corrected');

-- A131-06 · Q_SR_min — Mindest-Raeumvolumenstrom (Feststoffbilanz)
update public.fields set verification_status='verified_against_standard', verification_quote='Das Räumsystem muss so ausgelegt werden, dass der geräumte Räumvolumenstrom $Q_{\mathrm{SR}}$ die Feststoffbilanz nach GL. (B.9) erfüllt. Demnach gilt: | Q_{\mathrm{SR}} \geq \frac{Q_{\mathrm{RS}} \cdot T S_{\mathrm{RS}}-Q_{\mathrm{K}} \cdot T S_{\mathrm{BB}}}{T S_{\mathrm{BS}}}\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{B.9} — printed p.64', verification_note='md-verified 2026-09-07 (§B.4, printed p.64) [VC]', verified_at=now() where id='eadee273-306f-4568-8515-d27c51603b24' and verification_status not in ('verified_against_standard','corrected');

-- A131-06 · Q_K — Kurzschlussschlammstrom
update public.fields set verification_status='verified_against_standard', verification_quote='Da der Räumvolumenstrom $Q_{\mathrm{SR}}$ häufig kleiner ist als der Rücklaufschlammstrom $Q_{\mathrm{RS}}$, stellt sich bei Schildräumern zwischen Einlauf und Schlammabzug und bei Saugräumern aus der Zone oberhalb der Eindickzone ein Kurzschlussschlammstrom $Q_{K}$ ein. Es gilt: | Q_{K}=Q_{R S}-Q_{S R}\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{B.1} | Der Kurzschlussschlammstrom $Q_{K}$ nach GL. (B.1) liegt in Abhängigkeit vom Rücklaufschlammstrom erfahrungsgemäß zwischen $0,4 Q_{\text {RS }}$ bis $0,8 Q_{\text {RS }}$. — printed p.62', verification_note='md-verified 2026-09-07 (§B.1, printed p.62) [VC]', verified_at=now() where id='c4d5a46f-2963-4c29-8c98-318ea5673703' and verification_status not in ('verified_against_standard','corrected');

