-- A131-06 · h_1 — Klarwasserzonentiefe
update public.fields set verification_status='verified_against_standard', verification_quote='Bild 9 zeigt die Anordnung der Klarwasserzone für unterschiedliche Ablaufkonstruktionen. Grundsätzlich beginnt die Klarwasserzone auf Höhe des Wasserspiegels und reicht 50 cm nach unten (Fälle a), b) und d)). Bei eingehängten Rinnen (beidseitig oder einseitig von außen angeströmt) reicht die Klarwasserzone vom Wasserspiegel bis 20 cm unterhalb der Rinnenunterkante (Bild 9c). — printed p.43–46', verification_note='md-verified 2026-09-07 (§6.7, printed p.43–46) [VC]', verified_at=now() where id='52f5d4bd-2262-4bdc-b136-9b06c6c75d15' and verification_status not in ('verified_against_standard','corrected');

-- A131-06 · h_ges — Gesamtbeckentiefe Nachklaerbecken
update public.fields set verification_status='verified_against_standard', verification_quote='Die errechnete Beckentiefe $h_{\text {ges }}$ als Summe aus den Teiltiefen $h_{1}, h_{23}$ und $h_{4}$ ist für horizontal durchströmte Nachklärbecken mit geneigter Beckensohle auf zwei Drittel des Fließwegs einzuhalten. Sie muss dort mindestens 3 m betragen. Bei runden Nachklärbecken darf die Randwassertiefe $2,5 \mathrm{~m}$ nicht unterschreiten. — printed p.43–46', verification_note='md-verified 2026-09-07 (§6.7, printed p.43–46) [VC]', verified_at=now() where id='db4b6cb2-d385-4b80-a1b8-11c37db3f8af' and verification_status not in ('verified_against_standard','corrected');

