update public.fields set verification_status='verified_against_standard', verification_quote='Der minimale Sauerstoffbedarf auf Anlagen ohne einen signifikanten auch in den Nachtstunden zufließenden Frachtanteil ergibt sich vereinfacht über den Ansatz der endogenen Atmung als Anteil am gesamten Sauerstoffverbrauch für die Kohlenstoffelimination: | O V_{\mathrm{h}, \min }=\frac{O V_{\mathrm{d}, \mathrm{C}, \mathrm{aM}}}{\left(\frac{3,92}{t_{\mathrm{TS}} \cdot 1,072^{(\mathrm{TaM}-15)}}+1,66\right) \cdot 24}\left(\mathrm{~kg} \mathrm{O}_{2} / \mathrm{h}\right) \tag{63} — printed p.50–52', verification_note='md-verified 2026-09-07 (§7.3, printed p.50–52) [VC]', verified_at=now() where id='e141456b-4ffd-4b66-ac13-53e1545d0c68' and verification_status not in ('verified_against_standard','corrected');

-- A131-07 · f_int — Erhoehungsfaktor intermittierende Belueftung
update public.fields set verification_status='verified_against_standard', verification_quote='Bei intermittierender Belüftung sind die belüftungsfreien Zeiten über einen Erhöhungsfaktor ( $f_{\text {int }}$ ) entsprechend zu berücksichtigen: | f_{\mathrm{int}}=\frac{1}{1-V_{\mathrm{D}} / V_{\mathrm{BB}}}(-1) \tag{64} — printed p.50–52', verification_note='md-verified 2026-09-07 (§7.3, printed p.50–52) [VC]', verified_at=now() where id='e4d978c3-336f-42b7-b9fc-c92ea784e869' and verification_status not in ('verified_against_standard','corrected');

-- A131-08 · S_KS_ZB — Saeurekapazitaet im Zulauf Belebung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Säurekapazität im Zulauf zum Belebungsbecken ( $S_{K S, Z B}$ in $\mathrm{mmol} / \mathrm{l}$ ) resultiert in erster Linie aus der Säurekapazität (Härte) des Trinkwassers sowie der durch Ammonifikation des Harnstoffs und des organisch gebundenen Stickstoffs gebildeten Säurekapazität. — printed p.52–53', verification_note='md-verified 2026-09-07 (§7.4, printed p.52–53) [VC]', verified_at=now() where id='81d107d9-85bf-4567-8736-3769d58dc10b' and verification_status not in ('verified_against_standard','corrected');

-- A131-08 · S_NH4_ZB — Ammoniumstickstoff im Zulauf
update public.fields set verification_status='verified_against_standard', verification_quote='Die Säurekapazität nimmt durch Nitrifikation (unter Einrechnung des Rückgewinns aus der Denitrifikation) und der Phosphatfällung angenähert wie folgt ab: | S_{K S, A B}=S_{K S, Z B}-\left[0,07 \cdot\left(S_{N H 4, Z B}-S_{N H 4, A N}+S_{N O 3, A N}-S_{N O 3, Z B}\right)+0,06 \cdot S_{\mathrm{Fe} 3}+0,04 \cdot S_{\mathrm{Fe} 2}+0,11 \cdot S_{\mathrm{Al} 3}-0,03 \cdot X_{P, F \text { äll }}\right](\mathrm{mmol} / \mathrm{l}) \tag{65} — printed p.52–53', verification_note='md-verified 2026-09-07 (§7.4, printed p.52–53) [VC]', verified_at=now() where id='35b48c68-7f8f-4f59-af1f-2b47bbf842ef' and verification_status not in ('verified_against_standard','corrected');

-- A131-08 · S_Fe3 — Dosierung Eisen(III)
update public.fields set verification_status='verified_against_standard', verification_quote='Sowohl durch Nitrifikation als auch durch Zugabe von Metallsalzen ( $\mathrm{Fe}^{2+}, \mathrm{Fe}^{3+}, \mathrm{Al}^{3+}$ ) zur Phosphorelimination wird die Säurekapazität (Konzentration von Hydrogencarbonat, Bestimmung nach DIN 38409-7) vermindert. | S_{K S, A B}=S_{K S, Z B}-\left[0,07 \cdot\left(S_{N H 4, Z B}-S_{N H 4, A N}+S_{N O 3, A N}-S_{N O 3, Z B}\right)+0,06 \cdot S_{\mathrm{Fe} 3}+0,04 \cdot S_{\mathrm{Fe} 2}+0,11 \cdot S_{\mathrm{Al} 3}-0,03 \cdot X_{P, F \text { äll }}\right](\mathrm{mmol} / \mathrm{l}) \tag{65} — printed p.52–53', verification_note='md-verified 2026-09-07 (§7.4, printed p.52–53) [VC]', verified_at=now() where id='3f4303f2-fb2c-4030-a8d3-93d6b2aabf8c' and verification_status not in ('verified_against_standard','corrected');

