-- A131-08 · S_KS_AB — Verbleibende Saeurekapazitaet im Ablauf
update public.fields set verification_status='verified_against_standard', verification_quote='Die im Tagesmittel verbleibende Säurekapazität ist für den ungünstigsten Lastfall, d. h. in der Regel bei weitgehender Nitrifikation und eingeschränkter Denitrifikation sowie höchster Fällmitteldosierung zu ermitteln. | Die Säurekapazität sollte den Wert von $S_{K S, A B}=1,5 \mathrm{mmol} / \mathrm{l}$ nicht unterschreiten, gegebenenfalls müssen basische Neutralisationsmittel dosiert werden. — printed p.52–53', verification_note='md-verified 2026-09-07 (§7.4, printed p.52–53) [VC]', verified_at=now() where id='5e50b6fa-fa4b-4271-a552-72cf8c55b225' and verification_status not in ('verified_against_standard','corrected');

-- Gl.1 · A131-02 · C_CSB_ZB
update public.equations set verification_quote='Der CSB im Zufluss zu einer biologischen Anlage lässt sich nach Bild 4 in eine gelöste und eine partikuläre Fraktion unterteilen. Dabei ist zu beachten, dass alle Konzentrationen auf den Abwasserzufluss bezogen sind; das gilt auch für die berechneten Größen $O V_{C}, X_{C S B, \text { üs }}$ usw. Es gilt: | C_{\mathrm{CSB}, \mathrm{ZB}}=S_{\mathrm{CSB}, \mathrm{ZB}}+X_{\mathrm{CSB}, \mathrm{ZB}}(\mathrm{mg} / \mathrm{l}) \tag{1} — printed p.25–27', verification_note='md-verified 2026-09-07 (§4.2, Gl. 1, printed p.25–27) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='e83070a8-b8db-4ccf-b976-59ce92e51cb0' and verification_quote is null;

-- Gl.2 · A131-02 · C_CSB_ZB_frak
update public.equations set verification_quote='Jede der beiden Fraktionen besteht aus einer abbaubaren und einer inerten Fraktion: | C_{\mathrm{CSB}, \mathrm{ZB}}=S_{\mathrm{CSB}, \mathrm{abb}, \mathrm{ZB}}+S_{\mathrm{CSB}, \mathrm{inert}, \mathrm{ZB}}+X_{\mathrm{CSB}, \mathrm{abb}, \mathrm{ZB}}+X_{\mathrm{CSB}, \mathrm{inert}, \mathrm{ZB}}(\mathrm{mg} / \mathrm{l}) \tag{2} — printed p.25–27', verification_note='md-verified 2026-09-07 (§4.2, Gl. 2, printed p.25–27) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='c6b6455b-4867-47b3-a20f-572e8cb162e2' and verification_quote is null;

-- Gl.3 · A131-02 · S_CSB_inert_ZB
update public.equations set verification_quote='Die gelöste inerte Fraktion kann näherungsweise mit der gelösten CSB-Konzentration im Ablauf der Nachklärung gleichgesetzt werden: | S_{\mathrm{CSB}, \text { inert }, \mathrm{ZB}}=S_{\mathrm{CSB}, \text { inert }, \mathrm{AN}}=S_{\mathrm{CSB}, \mathrm{AN}}=f_{\mathrm{S}} \cdot C_{\mathrm{CSB}, \mathrm{ZB}}(\mathrm{mg} / \mathrm{l}) \tag{3} — printed p.25–27', verification_note='md-verified 2026-09-07 (§4.2, Gl. 3, printed p.25–27) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='48a36085-e583-4858-a96b-230fa1b305bf' and verification_quote is null;

-- Gl.4 · A131-02 · X_CSB_inert_ZB
update public.equations set verification_quote='Der inerte Teil des partikulären CSB kann ebenfalls als Anteil des gesamten partikulären CSB geschätzt werden: | X_{\mathrm{CSB}, \text { inert }, \mathrm{ZB}}=f_{\mathrm{A}} \cdot X_{\mathrm{CSB}, \mathrm{ZB}}=f_{\mathrm{A}} \cdot\left(C_{\mathrm{CSB}, \mathrm{ZB}}-S_{\mathrm{CSB}, \mathrm{ZB}}\right)(\mathrm{mg} / \mathrm{l}) \tag{4} — printed p.25–27', verification_note='md-verified 2026-09-07 (§4.2, Gl. 4, printed p.25–27) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='12842d15-2735-4216-89a6-7632ed3f276b' and verification_quote is null;

-- Gl.5 · A131-02 · C_CSB_abb_ZB
update public.equations set verification_quote='Der abbaubare CSB ( $C_{\mathrm{CSB}, \mathrm{abb}, \mathrm{ZB}}$ ) lässt sich dann wie folgt angeben: | C_{\mathrm{CSB}, \mathrm{abb}, \mathrm{ZB}}=C_{\mathrm{CSB}, \mathrm{ZB}}-S_{\mathrm{CSB}, \text { inert }, \mathrm{AN}}-X_{\mathrm{CSB}, \text { inert }, \mathrm{ZB}}(\mathrm{mg} / \mathrm{l}) \tag{5} — printed p.25–27', verification_note='md-verified 2026-09-07 (§4.2, Gl. 5, printed p.25–27) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='43420282-ef40-4c1b-a9ce-10ff2302cfc8' and verification_quote is null;

-- Gl.6 · A131-02 · C_CSB_la_ZB
update public.equations set verification_quote='C_{\mathrm{CSB}, \mathrm{la}, \mathrm{ZB}}=f_{\mathrm{CSB}} \cdot C_{\mathrm{CSB}, \mathrm{abb}, \mathrm{ZB}}(\mathrm{mg} / \mathrm{l}) \tag{6} | Der leicht abbaubare CSB ( $C_{\text {CSB, la,ZB }}$ ) kann über eine respirometrische Messung bestimmt werden (Henze 1995, Choubert 2013). — printed p.25–27', verification_note='md-verified 2026-09-07 (§4.2, Gl. 6, printed p.25–27) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='effdcffa-72d9-4793-8f46-dcd47964435a' and verification_quote is null;

-- Gl.7 · A131-02 · X_TS_ZB
update public.equations set verification_quote='Die abfiltrierbaren Stoffe des Zulaufs ( $X_{\mathrm{TS}, \mathrm{ZB}}$ ) bestehen aus der organischen und der anorganischen Fraktion, letztere geht nicht in $C_{\text {CSB,ZB }}$ ein (siehe Bild 4). | X_{\mathrm{TS}, \mathrm{ZB}}=X_{\text {orgTS }, \mathrm{ZB}}+X_{\text {anorg } \mathrm{TS}, \mathrm{ZB}}(\mathrm{mg} / \mathrm{l}) \tag{7} — printed p.25–27', verification_note='md-verified 2026-09-07 (§4.2, Gl. 7, printed p.25–27) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='187eed86-86a8-41ac-8b42-9dfe988a0259' and verification_quote is null;

