update public.equations set verification_quote='Der partikuläre CSB (CSB der abfiltrierbaren Stoffe) wird in der Regel nicht analytisch bestimmt, sondern ergibt sich als: | X_{\mathrm{CSB}, \mathrm{ZB}}=C_{\mathrm{CSB}, \mathrm{ZB}}-S_{\mathrm{CSB}, \mathrm{ZB}}(\mathrm{mg} / \mathrm{l}) \tag{9} — printed p.25–27', verification_note='md-verified 2026-09-07 (§4.2, Gl. 9, printed p.25–27) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='a69c701c-a7c5-4222-bbb1-0c614d073748' and verification_quote is null;

-- Gl.10 · A131-02 · X_CSB_ZB_oTS
update public.equations set verification_quote='Wenn $\mathrm{S}_{\mathrm{CSB}, \mathrm{ZB}}$ nicht bekannt ist, aber $X_{\mathrm{TS}, \mathrm{ZB}}$ gemessen wurde, kann der partikuläre CSB aus der organischen Trockensubstanz zu $1,6 \mathrm{~g}$ CSB/g oTS abgeschätzt werden. Damit lässt sich folgende Beziehung aufstellen: | X_{\mathrm{CSB}, \mathrm{ZB}}=C_{\mathrm{CSB}, \mathrm{ZB}}-S_{\mathrm{CSB}, \mathrm{ZB}}=X_{\mathrm{TS}, \mathrm{ZB}} \cdot 1,6 \cdot\left(1-f_{\mathrm{B}}\right)(\mathrm{mg} / \mathrm{l}) \tag{10} — printed p.25–27', verification_note='md-verified 2026-09-07 (§4.2, Gl. 10, printed p.25–27) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='bdd8f1fe-b64e-4fb4-9487-8f81c54e03d2' and verification_quote is null;

