update public.equations set verification_quote='Es ergibt sich unter zusätzlicher Berücksichtigung der anorganischen abfiltrierbaren Stoffe des Zulaufs: | \ddot{U} S_{\mathrm{d}, \mathrm{C}}=Q_{\mathrm{d}, \text { Konz }} \cdot\left(\frac{X_{\mathrm{CSB}, \text { inert }, \mathrm{ZB}}}{1,33}+\frac{X_{\mathrm{CSB}, \mathrm{BM}}+X_{\mathrm{CSB}, \text { inert,BM }}}{0,92 \cdot 1,42}+X_{\text {anorgTS,ZB }}\right) / 1000(\mathrm{~kg} / \mathrm{d}) \tag{24} — printed p.34', verification_note='md-verified 2026-09-07 (§5.2.2, Gl. 24, printed p.34) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='6785dedc-e925-4de3-b62c-77771e2fab2c' and verification_quote is null;

