update public.equations set verification_quote='\ddot{U}_{\mathrm{d}, \mathrm{C}}=Q_{\mathrm{d}, \text { Konz }} \cdot\left(\frac{X_{\mathrm{CSB}, \text { inert }, \mathrm{ZB}}}{1,33}+\frac{X_{\mathrm{CSB}, \mathrm{BM}}+X_{\mathrm{CSB}, \text { inert,BM }}}{0,92 \cdot 1,42}+f_{\mathrm{B}} \cdot X_{\mathrm{TS}, \mathrm{ZB}}\right) / 1000(\mathrm{~kg} / \mathrm{d}) \tag{25} — printed p.34', verification_note='md-verified 2026-09-07 (§5.2.2, Gl. 25, printed p.34) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='a4fadbdd-c81b-49c4-870d-d0cdcbd46284' and verification_quote is null;

-- Gl.26 · A131-04 · S_NO3_D
update public.equations set verification_quote='Die im Tagesmittel zu denitrifizierende Nitratstickstoffkonzentration ( $\mathrm{S}_{\mathrm{N} 03, \mathrm{D}}$ ) ergibt sich wie folgt: | S_{\mathrm{NO} 3, \mathrm{D}}=C_{\mathrm{N}, \mathrm{ZB}}-S_{\text {orgN,AN }}-S_{\mathrm{NH} 4, \mathrm{AN}}-S_{\mathrm{NO} 3, \mathrm{AN}}-X_{\text {orgN,BM }}-X_{\text {orgN,inert }}(\mathrm{mg} / \mathrm{l}) \tag{26} — printed p.34–35', verification_note='md-verified 2026-09-07 (§5.2.3, Gl. 26, printed p.34–35) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='5772ad83-4986-4e08-b771-7c2f30a98053' and verification_quote is null;

-- Gl.27 · A131-04 · OV_C
update public.equations set verification_quote='In einem ersten Schritt wird der gesamte Sauerstoffverbrauch für den Kohlenstoffabbau $O V_{\mathrm{C}}$ aus der CSB-Bilanz errechnet: | O V_{C}=C_{C S B, \mathrm{abb}, \mathrm{ZB}}+C_{C S B, \mathrm{dos}}-X_{C S B, \mathrm{BM}}-X_{C S B, \text { inert,BM }}(\mathrm{mg} / \mathrm{l}) \tag{27} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, Gl. 27, printed p.35–36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='520a65fa-ae25-47e3-bf24-05e30d28893f' and verification_quote is null;

-- Gl.28 · A131-04 · OV_C_la_vorg
update public.equations set verification_quote='Für die vorgeschaltete Denitrifikation ergibt sich für diesen Anteil: | O V_{\mathrm{C}, \mathrm{la}, \mathrm{vorg}}=f_{\mathrm{CSB}} \cdot C_{\mathrm{CSB}, \mathrm{abb}, \mathrm{ZB}} \cdot(1-Y)+C_{\mathrm{CSB}, \mathrm{dos}} \cdot\left(1-Y_{\mathrm{CSB}, \mathrm{dos}}\right)(\mathrm{mg} / \mathrm{l}) \tag{28} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, Gl. 28, printed p.35–36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='e81c6dda-429b-4d54-bfdd-3d7f469bc77f' and verification_quote is null;

-- Gl.29 · A131-04 · OV_C_la_int
update public.equations set verification_quote='Für die intermittierende Denitrifikation kann nur die extern dosierte Kohlenstoffquelle separat gerechnet werden. Wenn diese während der Denitrifikationszeit dosiert wird, dann ergibt sich: | O V_{\text {C,la,int }}=C_{\text {CSB,dos }} \cdot\left(1-Y_{\text {CSB,dos }}\right)(\mathrm{mg} / \mathrm{l}) \tag{29} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, Gl. 29, printed p.35–36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='a86ec602-51e4-4e5b-858e-fa2b146546fb' and verification_quote is null;

-- Gl.30 · A131-04 · OV_C_D_vorg
update public.equations set verification_quote='vorgeschaltete Denitrifikation: | O V_{C, D}=0,75 \cdot\left[O V_{C, l, \text { vorg }}+\left(O V_{C}-O V_{C, l, \text { avorg }}\right) \cdot\left(V_{D} / V_{B B}\right)^{0,68}\right](\mathrm{mg} / \mathrm{l}) \tag{30} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, Gl. 30, printed p.35–36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='fb3bf5b5-5ad4-462e-b6dc-7e2c8ccf870c' and verification_quote is null;

-- Gl.31 · A131-04 · OV_C_D_int
update public.equations set verification_quote='intermittierende Denitrifikation mit Dosierung von externem Substrat während der Denitrifikationszeit: | O V_{C, D}=0,75 \cdot\left[O V_{C, l \mathrm{a}, \text { int }}+\left(O V_{C}-O V_{C, l \mathrm{a}, \text { int }}\right) \cdot\left(V_{D} / V_{B B}\right)\right](\mathrm{mg} / \mathrm{l}) \tag{31} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, Gl. 31, printed p.35–36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='39959d38-56ee-4ec1-a5ef-b0712389a9e8' and verification_quote is null;

-- Gl.32 · A131-04 · OV_C_D_sim
update public.equations set verification_quote='simultane Denitrifikation ohne vorgeschaltete Anaerobbecken: | O V_{C, D}=0,75 \cdot O V_{C} \cdot V_{D} / V_{B B}(\mathrm{mg} / \mathrm{l}) \tag{32} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, Gl. 32, printed p.35–36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='5c72b666-ed1d-4132-9dfa-c4bfe77fcbc2' and verification_quote is null;

-- Gl.33 · A131-04 · OV_C_D_vg
update public.equations set verification_quote='Der Anteil des Sauerstoffverbrauchs der vorgeschalteten Denitrifikationsstufe ergibt sich bei Verfahrenskombination, wenn in GL. (30) der Denitrifikationsanteil des vorgeschalteten Denitrifikationsbeckens eingesetzt wird: | O V_{\mathrm{C}, \mathrm{D}, \mathrm{vg}}=0,75 \cdot\left[O V_{\mathrm{C}, \mathrm{la}, \mathrm{vorg}}+\left(O V_{\mathrm{C}}-O V_{\mathrm{C}, \mathrm{la}, \mathrm{vorg}}\right) \cdot\left(V_{\mathrm{D}, \mathrm{vg}} / V_{\mathrm{BB}}\right)^{0,68}\right](\mathrm{mg} / \mathrm{l}) \tag{33} — printed p.35–36', verification_note='md-verified 2026-09-07 (§5.2.4, Gl. 33, printed p.35–36) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='9b4fd88f-a09c-4cea-b0b1-8780a1036e10' and verification_quote is null;

-- Gl.34 · A131-04 · x_iter
update public.equations set verification_quote='Der Nachweis einer ausreichenden Reduzierung der Nitratkonzentration wird über den Vergleich von Sauerstoffzehrung $\left(O V_{C, D}\right)$ zu Sauerstoffangebot aus Nitrat $=2,86 \cdot S_{\mathrm{N} 03, \mathrm{D}}$ geführt. Die Iteration über eine Veränderung der $V_{D} / V_{B B}$ wird so lange geführt, bis der Wert | x=\frac{O V_{C, D}}{2,86 \cdot S_{N O 3, D}} \tag{34} | den Wert 1 annimmt. — printed p.36–37', verification_note='md-verified 2026-09-07 (§5.2.5, Gl. 34, printed p.36–37) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='99707a5d-e57c-4ac0-9084-317e68f7c8fc' and verification_quote is null;

-- Gl.35 · A131-05 · X_P_Faell
update public.equations set verification_quote='Zur Ermittlung des zu fällenden Phosphats ( $X_{\text {P,Fäll }}$ ) ist eine Phosphorbilanz, gegebenenfalls für verschiedene Lastfälle aufzustellen: | X_{P, F \text { äll }}=C_{P, Z B}-C_{P, A N}-X_{P, B M}-X_{P, B i o P}(\mathrm{mg} / \mathrm{l}) \tag{35} — printed p.37–38', verification_note='md-verified 2026-09-07 (§5.3.1, Gl. 35, printed p.37–38) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='fff98476-27ab-4ac2-a842-d34afe0746f7' and verification_quote is null;

