-- Gl.37 · A131-05 · UeS_d
update public.equations set verification_quote='Der in einer Belebungsanlage produzierte Schlamm setzt sich aus den beim Abbau organischer Stoffe entstehenden und eingelagerten Feststoffen (siehe 5.2) sowie dem aus der Phosphorelimination resultierenden Schlamm (siehe 5.3) zusammen: | \ddot{U} S_{d}=\ddot{U} S_{d, C}+\ddot{U} S_{d, P}(\mathrm{~kg} / \mathrm{d}) \tag{37} — printed p.38–39', verification_note='md-verified 2026-09-07 (§5.4, Gl. 37, printed p.38–39) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='b1ae89ef-9b86-4511-a173-7a64e5027f23' and verification_quote is null;

