-- Gl.63 · A131-07 · OV_h_min
update public.equations set verification_quote='Der minimale Sauerstoffbedarf auf Anlagen ohne einen signifikanten auch in den Nachtstunden zufließenden Frachtanteil ergibt sich vereinfacht über den Ansatz der endogenen Atmung als Anteil am gesamten Sauerstoffverbrauch für die Kohlenstoffelimination: | O V_{\mathrm{h}, \min }=\frac{O V_{\mathrm{d}, \mathrm{C}, \mathrm{aM}}}{\left(\frac{3,92}{t_{\mathrm{TS}} \cdot 1,072^{(\mathrm{TaM}-15)}}+1,66\right) \cdot 24}\left(\mathrm{~kg} \mathrm{O}_{2} / \mathrm{h}\right) \tag{63} — printed p.50–52', verification_note='md-verified 2026-09-07 (§7.3, Gl. 63, printed p.50–52) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='7cc3f392-b5c2-47ac-b795-8a054f171ff9' and verification_quote is null;

