-- Gl.B.5 · A131-06 · t_SR_recht
update public.equations set verification_quote='Für Schildräumer ergibt sich mit der Fahrstrecke $l_{W}$ des Räumwagens ( $l_{W} \approx l_{N B}$ ) das Räumintervall unter Berücksichtigung der Zeit für das Heben und Absenken des Räumschildes $t_{\mathrm{s}}(\mathrm{h})$ zu: | t_{\mathrm{SR}}=\frac{l_{\mathrm{W}}}{v_{\mathrm{SR}}}+\frac{l_{\mathrm{W}}}{v_{\text {Rück }}}+t_{\mathrm{s}}(\mathrm{~h}) \tag{B.5} — printed p.63–64', verification_note='md-verified 2026-09-07 (§B.3, Gl. B.5, printed p.63–64) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='cf276fa9-1763-47a8-a711-e81d2239c787' and verification_quote is null;

-- Gl.B.6 · A131-06 · Q_SR_recht
update public.equations set verification_quote='Der Räumvolumenstrom $Q_{\mathrm{SR}}$ ergibt sich bei Annahme eines Abstands des Räumschilds von dem Schlammabzugspunkt beim Einsetzen des Schlammrückflusses von $l_{S R} \approx 15 \cdot h_{S R}$ mit der Räumschildlänge $b_{\mathrm{SR}}\left(\approx b_{\mathrm{NB}}\right.$ in Becken mit senkrechten Wänden) zu: | Q_{\mathrm{SR}}=\frac{h_{\mathrm{SR}} \cdot b_{\mathrm{SR}} \cdot l_{\mathrm{SR}}}{f_{\mathrm{SR}} \cdot t_{\mathrm{SR}}}\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{B.6} — printed p.63–64', verification_note='md-verified 2026-09-07 (§B.3, Gl. B.6, printed p.63–64) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='72e3e608-48c7-433d-b759-2602b23eb9e0' and verification_quote is null;

