-- Gl.B.9 · A131-06 · Q_SR_min
update public.equations set verification_quote='Das Räumsystem muss so ausgelegt werden, dass der geräumte Räumvolumenstrom $Q_{\mathrm{SR}}$ die Feststoffbilanz nach GL. (B.9) erfüllt. Demnach gilt: | Q_{\mathrm{SR}} \geq \frac{Q_{\mathrm{RS}} \cdot T S_{\mathrm{RS}}-Q_{\mathrm{K}} \cdot T S_{\mathrm{BB}}}{T S_{\mathrm{BS}}}\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{B.9} — printed p.64', verification_note='md-verified 2026-09-07 (§B.4, Gl. B.9, printed p.64) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='797e827f-378b-44b3-8263-2125cf8e9ca3' and verification_quote is null;

-- Gl.C.1 · A131-06 · h_2
update public.equations set verification_quote='Die Trennung (Begriff „Übergang" aus der Bezeichnung der Zone) von Klarwasser und Schlamm wird mit einem empirischen Anteil berücksichtigt, der eine rechnerische Durchflusszeit von einer halben Stunde bezogen auf das freie Wasservolumen vorsieht. Der Rücklaufschlammstrom wird bei dieser Betrachtung mit berücksichtigt. Die Einzelhöhe $h_{2}$ errechnet sich aus GI. (C.1). | h_{2}=\frac{0,5 \cdot q_{A} \cdot(1+R V)}{1-V S V / 1.000}(\mathrm{~m}) \tag{C.1} — printed p.64–65', verification_note='md-verified 2026-09-07 (§C, Gl. C.1, printed p.64–65) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='a0226158-e3df-4973-998f-942b6293bdfe' and verification_quote is null;

