-- Gl.hges · A131-06 · h_ges
update public.equations set verification_quote='Die errechnete Beckentiefe $h_{\text {ges }}$ als Summe aus den Teiltiefen $h_{1}, h_{23}$ und $h_{4}$ ist für horizontal durchströmte Nachklärbecken mit geneigter Beckensohle auf zwei Drittel des Fließwegs einzuhalten. Sie muss dort mindestens 3 m betragen. Bei runden Nachklärbecken darf die Randwassertiefe $2,5 \mathrm{~m}$ nicht unterschreiten. — printed p.43–46', verification_note='md-verified 2026-09-07 (§6.7, Gl. hges, printed p.43–46) [VC] — quote backfill only; verification_status was already verified_against_standard', verified_at=now() where id='2f29c3cb-70b8-4b80-a526-1397a031183c' and verification_quote is null;

